function M.resolve(opts)
  return R.resolve_at_cursor(opts)
end

function M.try_resolve_with_matches(matches, original_path, opts)
  opts = opts or {}
  local open_cmd = opts.open_cmd or "edit"

  if not matches or #matches == 0 then return false end

  -- === Show Selection UI ===
  local ui = require("gopath.alternate.ui")
  return ui.present_selection(matches, original_path, {
    open_cmd = open_cmd,
    line = opts.line,
    col = opts.col,
  })
end

function M.extract_filename(filepath)
  if not filepath or filepath == "" then return nil end

  return vim.fn.fnamemodify(filepath, ":t")
end

function M.file_meta(path)
  local stat = uv.fs_stat(path)
  if not stat then return nil end
  return string.format("%s, modified %s", human_size(stat.size), human_age(stat.mtime.sec))
end

