function M.get()
  return state
end

function M.open(path)
  if not path or path == "" then return false end

  local opener = require("gopath.external.helpers.opener")
  return opener.open_with_system(path)
end

function M.is_external_file(path, extra_extensions)
  return is_url(path) or has_external_extension(path, extra_extensions)
end

local function try_help(subject, target)
  local cmd = (target == "tab" and "tab help %s")
    or (target == "window" and "belowright help %s")
    or "help %s"
  return pcall(function()
    return vim.cmd((cmd):format(vim.fn.escape(subject, " ")))
  end)
end

function M.expand_cfile()
  -- Use smart token extraction
  local token_provider = require("gopath.providers.token")
  return token_provider.get_token()
end

function M.get_token()
  local custom = M.extract_at_cursor()
  if custom and custom ~= "" then return custom end
  return M.expand_cfile()
end

local function has_ts()
  return pcall(require, "vim.treesitter")
end

function M.parse_string(text, lang)
  if not has_ts() then return nil end
  local ok, parser = pcall(vim.treesitter.get_string_parser, text, lang)
  if not ok or not parser then return nil end
  local ok2, trees = pcall(function()
    return parser:parse()
  end)
  if not ok2 or not trees or not trees[1] then return nil end
  return trees[1]:root()
end

function M.current_file_dir()
  return vim.fn.expand("%:p:h")
end

function M.current_line()
  return vim.api.nvim_get_current_line()
end

function M.cursor_col()
  return vim.api.nvim_win_get_cursor(0)[2] + 1
end

function M.resolve_cached(tail, opts)
  if not tail or tail == "" then return nil end
  opts = opts or {}
  local rng = (opts.line and opts.line > 0) and { line = opts.line, col = opts.col or 1 } or nil
  local cached = M.cache_lookup(tail, opts.max_components)
  if #cached == 0 then return nil end
  return make_result(M.pick_best(cached), #cached == 1 and 0.85 or 0.72, rng)
end

local function cur_tick(bufnr)
  return vim.api.nvim_buf_get_changedtick(bufnr)
end

local function cur_tick(buf)
  return vim.api.nvim_buf_get_changedtick(buf)
end

function M.get_chain_at_cursor()
  -- Prefer TS (more semantic), otherwise fall back to regex.
  return ts_chain_at_cursor() or regex_chain_at_cursor()
end

local function module_to_path(mod)
  return PATH.search_module(mod)
end

local function esc(str)
  return (str:gsub("([%%%^%$%(%)%.%[%]%*%+%-%?])", "%%%1"))
end

function M.locate(abs_path, base_chain, seek_key)
  if type(abs_path) ~= "string" or abs_path == "" then return nil end
  local lines = vim.fn.readfile(abs_path)
  if type(lines) ~= "table" or #lines == 0 then return nil end

  local segs = split_chain(base_chain) -- { ROOT, cfg, highlight, ... }
  if #segs == 0 then return nil end

  return ts_locate(lines, segs, seek_key, abs_path)
    or legacy_locate(lines, segs, seek_key, abs_path)
end

function M.string_key_text(str_node, src)
  local content = str_node:field("content")[1]
  if content then return M.node_text(content, src) or "" end
  local raw = M.node_text(str_node, src) or ""
  return raw:sub(2, -2)
end

local function parse_import(line)
  return line:match('@import%s*%(%s*"([^"]+)"%s*%)')
end

function M.is_truncated(path)
  if type(path) ~= "string" or path == "" then return false end

  return path:match("^%.%.%.") ~= nil -- starts with ... (three or more)
    or path:match("^…") ~= nil -- unicode ellipsis
end

local function is_excluded(name)
  return vim.tbl_contains(config.excluded_dirs, name)
end

function M._get_state()
  return state
end

function M.to_forward(path)
  if type(path) ~= "string" then return path end
  return (path:gsub("\\", "/"))
end

function M.merge_ranges(parsed, existing)
  -- If parsed has line info, prefer it
  if parsed and parsed.line then return {
    line = parsed.line,
    col = parsed.col or 1,
  } end

  -- Otherwise use existing
  if existing and existing.line then
    return {
      line = existing.line,
      col = existing.col or 1,
    }
  end

  -- No line info available
  return nil
end

function M.create_range(line, col)
  if not line or line == 0 then return nil end

  return {
    line = math.max(1, line),
    col = math.max(1, col or 1),
  }
end

function M.normalize_range(range)
  if not range then return nil end

  if not range.line or range.line == 0 then return nil end

  return {
    line = math.max(1, range.line),
    col = math.max(1, range.col or 1),
  }
end

function M.using_lib()
  return lib_notify ~= nil
end

function M.join(...)
  local parts = { ... }
  for i = 1, #parts do
    local s = parts[i] or ""
    s = s:gsub("[/\\]+", "/")
    if s:sub(-1) == "/" and i < #parts then s = s:sub(1, -2) end
    parts[i] = s
  end
  return table.concat(parts, "/")
end

local function first_segment(candidate)
  return candidate:match("^([^/\\]+)")
end

function M.call(fn, ...)
  return require("lib.lua.error").safe_call(fn, ...)
end

function M.scheduled_notifier()
  local config = require("gopath.config").get()
  if not config.dev_mode then return nil end
  return safe.wrap()
end
